import { z } from 'zod';

export const AddTaskSchema = z
    .object({
        name: z.string().min(1, 'اسم المهمة مطلوب'),
        employee_id: z.string().min(1, 'الموظف مطلوب'),
        start_time: z.date({
            required_error: 'تاريخ البداية مطلوب',
        }),
        end_time: z.date({
            required_error: 'تاريخ النهاية مطلوب',
        }),
        description: z.string().optional(),
        status: z.string().min(1, 'الحالة مطلوبة'),
    })
    .refine((data) => data.end_time >= data.start_time, {
        message: 'تاريخ النهاية يجب أن يكون بعد أو يساوي تاريخ البداية',
        path: ['end_time'],
    });

export type AddTaskFormValues = z.infer<typeof AddTaskSchema>;
