import { Form } from '@/components/ui/form';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { apiGet, apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { useEffect, useMemo, useState } from 'react';
import { Employee } from '@/types/employee.types';
import { format } from 'date-fns';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { toast } from 'sonner';
import SearchableSelectInputForm from '@/components/forms/SearchableSelectInputForm';
import SelectInputForm from '@/components/forms/SelectInputForm';
import TextInputForm from '@/components/forms/TextInputForm';
import TextAreaInputForm from '@/components/forms/TextAreaInputForm';
import { DateInputForm } from '@/components/forms/DateInputForm';
import { AddTaskFormValues, AddTaskSchema } from '../schemas/add-task-schema';

interface Props {
    open: boolean;
    setShow: (value: boolean) => void;
    handleRefreshTable: () => void;
}

export default function AddTaskForm({ open, setShow, handleRefreshTable }: Props) {
    const [error, setError] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [employees, setEmployees] = useState<{ name: string; value: string }[]>([]);
    const [employeesError, setEmployeesError] = useState<string | null>(null);

    const defaultValues = useMemo(() => {
        const today = new Date();
        return {
            name: '',
            employee_id: '',
            start_time: today,
            end_time: today,
            description: '',
            status: 'active',
        };
    }, []);

    const form = useForm<AddTaskFormValues>({
        resolver: zodResolver(AddTaskSchema),
        defaultValues,
    });

    useEffect(() => {
        if (open) {
            const today = new Date();
            form.reset({
                name: '',
                employee_id: '',
                start_time: today,
                end_time: today,
                description: '',
                status: 'active',
            });
            setError(null);
        }
    }, [open, form]);

    useEffect(() => {
        const fetchEmployees = async () => {
            try {
                const response = await apiGet({ endpoint: endpoints.employee.simpleList });
                const options = (response.data.data as Employee[]).map((employee: Employee) => ({
                    name: employee.name,
                    value: String(employee.id),
                }));
                setEmployees(options);
                setEmployeesError(null);
            } catch {
                setEmployeesError('تعذر تحميل قائمة الموظفين.');
            }
        };

        fetchEmployees();
    }, []);

    const onSubmit = async (data: AddTaskFormValues) => {
        setLoading(true);
        setError(null);

        const body = {
            name: data.name,
            employee_id: Number(data.employee_id),
            start_time: format(data.start_time, 'yyyy-MM-dd'),
            end_time: format(data.end_time, 'yyyy-MM-dd'),
            description: data.description?.trim() ?? '',
            status: data.status,
        };

        try {
            await apiPost({
                endpoint: endpoints.task.create,
                body,
            });
            toast('تم إضافة المهمة بنجاح');
            handleRefreshTable();
            setShow(false);
        } catch (err: any) {
            if (err.response?.data?.errors) {
                Object.entries(err.response.data.errors).forEach(([field, messages]) => {
                    form.setError(field as keyof AddTaskFormValues, {
                        type: 'manual',
                        message: (messages as string[]).join(', '),
                    });
                });
            } else {
                let errorMessage = 'حدث خطأ أثناء إرسال البيانات. يرجى المحاولة مرة أخرى.';
                if (err.response) {
                    errorMessage = err.response.data?.msg || errorMessage;
                } else if (err.request) {
                    errorMessage = 'تعذر الاتصال بالخادم. يرجى التحقق من اتصالك بالإنترنت.';
                }
                setError(errorMessage);
            }
        } finally {
            setLoading(false);
        }
    };

    return (
        <Form {...form}>
            <form onSubmit={form.handleSubmit(onSubmit)} className="mt-6">
                {error && (
                    <div className="mb-4 p-4 bg-red-100 border border-red-400 text-red-700 rounded-lg">
                        <div className="flex justify-between items-center">
                            <span>{error}</span>
                            <button type="button" onClick={() => setError(null)} className="text-red-700 hover:text-red-900">
                                ×
                            </button>
                        </div>
                    </div>
                )}
                <div className="grid sm:grid-cols-2 grid-cols-1 gap-4">
                    <TextInputForm name="name" label="اسم المهمة" placeholder="أدخل اسم المهمة" />
                    <SearchableSelectInputForm
                        name="employee_id"
                        placeholder="بحث عن الموظف"
                        label="الموظف"
                        options={employees}
                        error={employeesError}
                        data={true}
                    />
                    <DateInputForm name="start_time" label="بداية المهمة" placeholder="اختر التاريخ" />
                    <DateInputForm name="end_time" label="نهاية المهمة" placeholder="اختر التاريخ" />
                    <SelectInputForm
                        name="status"
                        label="الحالة"
                        options={[
                            { name: 'متاح', value: 'active' },
                            { name: 'غير متاح', value: 'not active' },
                        ]}
                        placeholder="الحالة"
                        data={true}
                    />
                    <div className="sm:col-span-2">
                        <TextAreaInputForm name="description" label="الوصف" placeholder="وصف المهمة (اختياري)" />
                    </div>
                </div>
                <div className="flex flex-row gap-4 mt-12">
                    <SecondaryButton
                        onClick={() => setShow(false)}
                        type="button"
                        className="w-full text-base leading-5 tracking-normal py-[10px] font-medium"
                    >
                        إلغاء
                    </SecondaryButton>
                    <PrimaryButton type="submit" className="w-full text-base leading-5 tracking-normal font-medium py-[10px]">
                        {loading ? 'جاري الحفظ...' : 'حفظ'}
                    </PrimaryButton>
                </div>
            </form>
        </Form>
    );
}
