import PlusIcon from '@/components/icons/popups/PlusIcon';
import { Dialog, DialogContent, DialogHeader } from '@/components/ui/dialog';
import AddTaskForm from '@/features/tasks/forms/AddTaskForm';
import { cn } from '@/lib/utils';

interface Props {
    open: boolean;
    setShow: (value: boolean) => void;
    handleRefreshTable: () => void;
}

export default function AddTaskPopup({ open, setShow, handleRefreshTable }: Props) {
    return (
        <Dialog open={open} onOpenChange={setShow}>
            <div
                className={cn('fixed inset-0', {
                    '!hidden': !open,
                })}
            />
            <DialogContent
                showCloseButton={false}
                className="max-w-[623px] rounded-lg p-8 bg-white-blue-50 font-cairo gap-0 [&_[aria-label=Close]]:opacity-0"
            >
                <DialogHeader className="flex flex-col items-center">
                    <div className="flex flex-row justify-between mb-4 w-full">
                        <div className="flex flex-row gap-2 items-center">
                            <PlusIcon />
                            <h3 className="text-[22px] font-bold text-primery-blue-500">إضافة مهمة</h3>
                        </div>
                    </div>
                    <div className="w-full border-b border-[#D1D1D1] !mt-0" />
                </DialogHeader>
                <AddTaskForm open={open} setShow={setShow} handleRefreshTable={handleRefreshTable} />
            </DialogContent>
        </Dialog>
    );
}
